async function saveGuideDraft(db,{tripId,placeId,guide=null,text='',sourceFile=null,provider='',sourceNote='',confirmedLink=false}){if(!confirmedLink||!tripId||!placeId)throw Error('Choose the exact trip stop and confirm the link before saving');const stops=await stopsForTrip(db,tripId);if(!stops.some(s=>s.placeId===placeId))throw Error('Selected place is not in this trip');if(!guide&&!String(text||'').trim())throw Error('No guide text or JSON content');if(guide&&(guide.format!=='sk-travel-field-guide'||!guide.place||!Array.isArray(guide.stops)||!guide.stops.length))throw Error('Guide JSON must follow the SK-Travel field-guide package contract');const records=await guidesForPlace(db,placeId),revisionNo=(records[0]?.revisionNo||0)+1,at=new Date().toISOString(),fileId=sourceFile?id('guide-file'):null,sourceHash=sourceFile?await digest(sourceFile):await digest(new Blob([guide?JSON.stringify(guide):text]));const row={guideRevisionId:id('guide-revision'),tripId,placeId,revisionNo,format:guide?'sk-travel-field-guide':'text-note',guide:guide?structuredClone(guide):null,text:String(text||''),title:guide?.place?.name||String(text||'').slice(0,80)||'Imported guide',provider:String(provider||'unspecified'),sourceNote:String(sourceNote||''),sourceHash,sourceFileId:fileId,reviewStatus:'needs_review',active:false,importedAt:at,approvedAt:null,approvedBy:null};const t=db.transaction([STORES.guides,STORES.guideFiles,STORES.history],'readwrite'),d=done(t);t.objectStore(STORES.guides).add(row);if(sourceFile)t.objectStore(STORES.guideFiles).add({fileId,tripId,placeId,name:sourceFile.name||'guide-source',mimeType:sourceFile.type||'application/octet-stream',size:sourceFile.size,sha256:sourceHash,blob:sourceFile,immutable:true,importedAt:at});t.objectStore(STORES.history).add({historyId:id('history'),tripId,placeId,action:'guide_revision_imported',at,details:{revisionNo,sourceHash,provider:row.provider}});await d;return row}
async function reviewGuide(db,guideRevisionId,{reviewer,confirmed=false,makeActive=false}){if(!confirmed||!String(reviewer||'').trim())throw Error('Review checkbox and reviewer name required');const t=db.transaction([STORES.guides,STORES.history],'readwrite'),d=done(t),gs=t.objectStore(STORES.guides),g=await req(gs.get(guideRevisionId));if(!g)throw Error('Guide revision not found');const at=new Date().toISOString();if(makeActive){const allRows=await req(gs.getAll());for(const old of allRows)if(old.placeId===g.placeId&&old.active)gs.put({...old,active:false})}const next={...g,reviewStatus:'user_reviewed',approvedBy:String(reviewer).trim(),approvedAt:at,active:makeActive?true:!!g.active};gs.put(next);t.objectStore(STORES.history).add({historyId:id('history'),tripId:g.tripId,placeId:g.placeId,action:makeActive?'guide_reviewed_and_activated':'guide_reviewed',at,details:{guideRevisionId,revisionNo:g.revisionNo}});await d;return next}
async function backupZip(db,tripId,onProgress){if(!globalThis.SKTravelV7Archive)throw Error('Portable archive module is not loaded');return globalThis.SKTravelV7Archive.backupZip(db,tripId,onProgress)}
async function restoreBackup(db,file){if(!globalThis.SKTravelV7Archive)throw Error('Portable archive module is not loaded');return globalThis.SKTravelV7Archive.restoreBackup(db,file)}
return Object.freeze({DB,VERSION,STORES,open,all,digest,createTrip,addStop,trips,stopsForTrip,placesForTrip,guideForPlace,guidesForPlace,addPhoto,photosForStop,saveCoordinates,nearbyCandidates,setCompleted,saveGuideDraft,reviewGuide,backupZip,restoreBackup,distanceMeters});
